const crypto = require('crypto');
const item = $input.first().json;
const b = item.body ?? item;
const hdrs = item.headers || {};
const rawFwd = hdrs['x-forwarded-for'] || hdrs['X-Forwarded-For'] || '';
const clientIP = String(rawFwd).split(',')[0].trim() || String(hdrs['x-real-ip'] || hdrs['X-Real-IP'] || '').trim() || 'unknown';
const cidrs = String($env.CASTUO_ALLOWED_IP_CIDRS || '').split(',').map((s) => s.trim()).filter(Boolean);
function ipToInt(ip) {
  const s = String(ip).replace(/^::ffff:/i, '');
  const parts = s.split('.').map(Number);
  if (parts.length !== 4 || parts.some((p) => !Number.isFinite(p) || p > 255)) return null;
  return ((parts[0] << 24) | (parts[1] << 16) | (parts[2] << 8) | parts[3]) >>> 0;
}
function parseCidr(spec) {
  const [addr, bits] = spec.split('/');
  const maskLen = bits ? parseInt(bits, 10) : 32;
  const base = ipToInt(addr.trim());
  if (base === null || maskLen < 0 || maskLen > 32) return null;
  const mask = maskLen === 32 ? 0xffffffff : (0xffffffff << (32 - maskLen)) >>> 0;
  return { base: base & mask, mask };
}
function ipAllowed(ip) {
  if (cidrs.length === 0) return true;
  const v = ipToInt(ip);
  if (v === null) return false;
  for (const c of cidrs) {
    const p = parseCidr(c);
    if (!p) continue;
    if ((v & p.mask) === (p.base & p.mask)) return true;
  }
  return false;
}
if (!ipAllowed(clientIP)) throw new Error('IP no autorizada: ' + clientIP);
const trazabilidad_id = 'TRACE-' + new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-' + crypto.randomUUID().slice(0, 8);
const zone = String($env.CASTUO_ZONE_ID || 'zone_default');
const rawType = String(b.sensor_type || 'ph');
const sensor_type = rawType === 'temperatura' ? 'temperature' : rawType === 'humedad' ? 'humidity' : rawType === 'luz' ? 'light' : rawType;
const sensor_id = String(b.sensor_id || `sensor_${rawType}_${zone}`);
const value = Number(b.value);
if (Number.isNaN(value)) throw new Error('value numérico requerido');
const ts = b.timestamp || new Date().toISOString();
const location = String(b.location || 'default');
const unit = rawType === 'ph' ? 'pH' : rawType === 'temperatura' ? '°C' : rawType === 'humedad' ? '%' : rawType === 'ec' ? 'mS/cm' : 'lux';
const reading = { sensor_id, sensor_type, value, timestamp: ts, location, unit, zone_id: zone };
const thrHi = b.threshold != null ? Number(b.threshold) : null;
const thrLo = b.threshold_low != null ? Number(b.threshold_low) : null;
let threshold_exceeded = false;
if (thrHi != null && !Number.isNaN(thrHi) && value > thrHi) threshold_exceeded = true;
if (thrLo != null && !Number.isNaN(thrLo) && value < thrLo) threshold_exceeded = true;
const hash_verificacion = crypto.createHash('sha256').update(JSON.stringify(reading)).digest('hex');
return [{ json: { reading, threshold_exceeded, body_raw: b, trazabilidad_id, hash_verificacion, client_ip: clientIP } }];

const castuo = $('POST_Lecturas_CASTUO').first().json;
const p = $('Code_Parse_IoT').first().json;
const r = p.reading;
const summary = 'Lectura IoT: ' + r.sensor_type + '=' + r.value + ' ' + r.unit + ', zona=' + r.zone_id + ', ubicación=' + r.location + '. Trazabilidad ' + p.trazabilidad_id + '. Respuesta CASTÚO: ' + JSON.stringify(castuo);
const mistral_messages = [
  { role: 'system', content: 'Eres agrónomo hidroponía UE. Breve, accionable, sin diagnóstico médico.' },
  { role: 'user', content: summary },
];
return [{ json: { mistral_messages, trace: { parsed: p, castuo } } }];

const mistral = $input.first().json;
const p = $('Code_Parse_IoT').first().json;
const sev = String(p.body_raw?.alert_severity || '').toUpperCase();
let assistant = '';
if (mistral.choices && mistral.choices[0] && mistral.choices[0].message) {
  assistant = String(mistral.choices[0].message.content || '');
} else {
  assistant = 'Mistral no disponible o error: ' + JSON.stringify(mistral).slice(0, 1200);
}
const daily_body = {
  analysis_date: new Date().toISOString(),
  zone_id: p.reading.zone_id,
  overall_status: p.threshold_exceeded ? 'attention_required' : 'normal_operation',
  issues: p.threshold_exceeded ? [{ type: 'threshold', message: 'Umbral: ' + p.reading.sensor_type + '=' + p.reading.value + ' ' + p.reading.unit }] : [],
  recommendations: assistant ? [assistant] : ['Sin recomendación automática'],
  trends: [{ type: 'mistral_or_iot', description: assistant.slice(0, 800) }],
  priority: p.threshold_exceeded ? 'high' : 'medium',
};
const slack_payload = { channel: '#hidroponia', message: p.reading.sensor_type + ' ' + (p.threshold_exceeded ? 'FUERA DE RANGO' : 'OK') + ': ' + p.reading.value + ' ' + p.reading.unit + ' @ ' + p.reading.zone_id };
const st = String(p.reading.sensor_type || '').toLowerCase();
let coste_estimado_perdida = 200;
if (st === 'temperature' || st === 'temperatura') coste_estimado_perdida = 500;
else if (st === 'ph') coste_estimado_perdida = 300;
let alert_type = 'OK';
if (p.threshold_exceeded) alert_type = sev === 'CRITICO' ? 'CRITICO' : 'NO_CONFORME';
let impacto_roi = 'Bajo (-1%)';
if (alert_type === 'CRITICO') impacto_roi = 'Alto (-15%)';
else if (alert_type === 'NO_CONFORME') impacto_roi = 'Medio (-5%)';
return [{ json: { daily_body, slack_payload, alert_type, coste_estimado_perdida, impacto_roi, codigo_trazabilidad: p.trazabilidad_id, location: p.reading.location } }];
